import * as React from 'react';
import { 
  DetailsList, 
  DetailsListLayoutMode, 
  SelectionMode, 
  IColumn,
  PrimaryButton,
  DefaultButton,
  Stack,
  IStackTokens
} from '@fluentui/react';
import { IRequest } from '../models/IRequest';

export interface IRequestManagerProps {
  requests: IRequest[];
  onApprove: (requestId: string) => void;
  onDecline: (requestId: string) => void;
}

const stackTokens: IStackTokens = { childrenGap: 8 };

export const RequestManager: React.FC<IRequestManagerProps> = (props) => {
  const columns: IColumn[] = [
    { key: 'col1', name: 'Date', fieldName: 'requestDate', minWidth: 80, maxWidth: 100 },
    { key: 'col2', name: 'Requester', fieldName: 'requesterName', minWidth: 100, maxWidth: 150 },
    { key: 'col3', name: 'Asset', fieldName: 'assetTitle', minWidth: 100, maxWidth: 150 },
    { key: 'col4', name: 'Type', fieldName: 'type', minWidth: 80, maxWidth: 100 },
    { key: 'col5', name: 'Qty', fieldName: 'quantity', minWidth: 40, maxWidth: 60 },
    { key: 'col6', name: 'Status', fieldName: 'status', minWidth: 80, maxWidth: 100 },
    { 
      key: 'col7', 
      name: 'Actions', 
      minWidth: 150, 
      maxWidth: 200,
      onRender: (item: IRequest) => {
        if (item.status !== 'Pending') return null;
        return (
          <Stack horizontal tokens={stackTokens}>
            <PrimaryButton 
              text="Approve" 
              onClick={() => props.onApprove(item.id)} 
              styles={{ root: { height: 24, fontSize: 12 } }}
            />
            <DefaultButton 
              text="Decline" 
              onClick={() => props.onDecline(item.id)} 
              styles={{ root: { height: 24, fontSize: 12 } }}
            />
          </Stack>
        );
      }
    }
  ];

  const pendingRequests = props.requests.filter(r => r.status === 'Pending');
  const otherRequests = props.requests.filter(r => r.status !== 'Pending');

  return (
    <div>
      <h4>Pending Requests ({pendingRequests.length})</h4>
      {pendingRequests.length > 0 ? (
        <DetailsList
          items={pendingRequests}
          columns={columns}
          layoutMode={DetailsListLayoutMode.justified}
          selectionMode={SelectionMode.none}
        />
      ) : (
        <p style={{ color: '#666', fontStyle: 'italic' }}>No pending requests.</p>
      )}

      {otherRequests.length > 0 && (
        <>
          <h4 style={{ marginTop: 20 }}>Request History</h4>
          <DetailsList
            items={otherRequests}
            columns={columns.filter(c => c.key !== 'col7')} // Hide actions for history
            layoutMode={DetailsListLayoutMode.justified}
            selectionMode={SelectionMode.none}
          />
        </>
      )}
    </div>
  );
};
